INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(3982, 'plPL', 'Co się dzieje?', 'Przysłano mnie tu z polecenia Thralla. Naprawdę myślisz, że ci błazni mogliby mnie pojmać? Dałem się złapać, żeby zebrać informacje.$B$B<Gor\'shak szepcze.>$B$BImperator Thaurissan porwał księżniczkę Żelaznej Kuźni. Księżniczka Miedziobroda jest w tym właśnie mieście! Założę się, że staremu Magniemu omal nie stanęło serce, gdy usłyszał tę wiadomość.$B$B<Gor\'shak się śmieje.>$B$BCiii! Słyszysz? Nadchodzą strażnicy! BROŃ SIĘ!', 'Obroń Gor\'shaka.', 'Przetrwaj natarcie', 'Porozmawiaj z dowódcą Gor\'shakiem w Otchłani Czarnej Góry.', '', '', '', '', 0),
(4083, 'plPL', 'Widmowy kielich', '', '', '', 'Wróć do Widmowego kielicha w Górach Alterak.', '', '', '', '', 0),
(4201, 'plPL', 'Eliksir miłosny', 'Och, katusze miłości! Mój drogi szeregowy Rocknot jest nieczuły na moje wdzięki. Odtrącił mnie! To doprowadza mnie do szału!$B$BMusisz mi pomóc! My, sukkuby, wiemy o miłości wiele, a ja potrafię uwarzyć eliksir, który skruszy żelazne mury wokół serca Rocknota. Potrzebuję do niego tych składników: ziela zwanego krwią Groma, olbrzymich żył srebra od klifowych olbrzymów z Aszary oraz wody z krateru Gorących Źródeł Golakka w Un\'Goro. Wodę możesz wlać do tej fiolki.$B$BProszę, $N, pomóż biednej duszy w poszukiwaniu szczęścia!', 'Przynieś 4 sztuki krwi Groma, 10 olbrzymich żył srebra i napełnioną fiolkę Nagmary pani Nagmarze w Otchłani Czarnej Góry.', '', 'Wróć do pani Nagmary w Otchłani Czarnej Góry.', '', '', '', '', 0),
(4241, 'plPL', 'Marszałek Windsor', 'Więc ten tchórz i nicpoń twierdzi, że Windsor żyje, tak?$B$BSzykuj się, $gzastępco:zastępczyni;, idziesz go odnaleźć. Jeśli Windsor żyje, masz go przyprowadzić. Jeśli nie żyje, chcę dowodu.$B$B<Maxwell się śmieje.>$B$BZałożę się, że masz już dość słuchania tego, co?', 'Udaj się na północny zachód do Czarnej Góry i wejdź do Otchłani Czarnej Góry. Dowiedz się, co stało się z marszałkiem Windsorem.$B$BPamiętasz, jak Obdarty John mówił, że Windsora zawleczono do więzienia.', '', '', '', '', '', '', 0),
(4242, 'plPL', 'Porzucona nadzieja', 'Bolvar to głupiec. Zbierałem jego cenne „dowody”, żeby mu je wepchnąć do gardła.$B$BTo ślepy błazen. Dowód stoi dwie stopy od niego, a on go nie widzi.$B$BCo do moich danych – przepadły. Zniknęły. Nie do odzyskania.$B$BJeśli kiedykolwiek odnajdę Żelaznego Wroga i wydostanę się z tego labiryntu, najpierw udam się do Wichrogrodu, żeby wbić młot między oczy temu gadowi.$B$BZostaw mnie, $N.', 'Przekaż złe wieści marszałkowi Maxwellowi w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', '', '', 0),
(4264, 'plPL', 'Zmięty liścik', 'Powierzchnię liściku pokrywają plamy. Tekst jest ledwo czytelny, ale udaje ci się odczytać:$B$B...słodka ironia...$B$B...upadek rozbitego Przymierza...$B$B...gdyby nie pilność generała Kuźni Gniewu, może nigdy nie odkrylibyśmy klucza do szyfru...$B$B...Argelmach niemal skończył odszyfrowywać notatki Windsora.$B$BNasz pan powstanie z głębin i zmiażdży wszystkich, którzy pozostaną...$B$B– Imperator Dagran Thaurissan.$B', 'Być może $gnatrafiłeś:natrafiłaś; właśnie na coś, co zainteresuje marszałka Windsora. Może jednak jest jeszcze nadzieja.', '', '', '', '', '', '', 0),
(4282, 'plPL', 'Strzęp nadziei', '<Marszałek Windsor z przejęciem potrząsa liścikiem.>$B$BRozumiesz, co to znaczy, $N?$B$BMoże nie wszystko stracone! Z tego, co mogę wywnioskować, informacje są w rękach dwóch Czarnorytych: generała Kuźni Gniewu i władcy golemów Argelmacha. Mam przeczucie, że nie oddadzą ich tylko dlatego, że grzecznie poprosimy.$B$BMam nadzieję, że jesteś $ggotów:gotowa; do walki.$B$BRuszaj i odnajdź tych dwóch łotrów! Zniszcz ich i zwróć mi moje zagubione informacje.', 'Zwróć zagubione informacje marszałka Windsora.$B$BMarszałek Windsor uważa, że informacje są w rękach władcy golemów Argelmacha i generała Kuźni Gniewu.', '', 'Wróć do marszałka Windsora w Otchłani Czarnej Góry.', '', '', '', '', 0),
(4295, 'plPL', 'Piwo Rocknota', '', '', '', 'Wróć do szeregowego Rocknota w Górach Alterak.', '', '', '', '', 0),
(4299, 'plPL', '<NYI> <TXT>Grobowiec Siedmiu', 'Odnajdź Grobowiec Siedmiu i umieść tam ten PX83-Enigmatron.', 'Umieść PX83-Enigmatron w Grobowcu Siedmiu, a następnie wróć do Maxworta Uberglinta.', 'Umieść PX83-Enigmatron', 'Wróć do Maxworta Uberglinta na Skale Upiornych Maczug na Płonących Stepach.', '', '', '', '', 0),
(4322, 'plPL', 'Ucieczka z więzienia!', 'Musimy się stąd wydostać, $N. Pomóż mi odzyskać mój ekwipunek z magazynu i uwolnić moich przyjaciół. Jeśli się stąd wydostaniemy, udaj się do Czuwania Morgana i porozmawiaj z marszałkiem Maxwellem. On przekaże ci dalsze instrukcje.', 'Pomóż marszałkowi Windsorowi odzyskać ekwipunek i uwolnić jego przyjaciół. Jeśli ci się uda, wróć do marszałka Maxwella.', 'Ucieczka z więzienia!', 'Wróć do marszałka Maxwella w Czuwaniu Morgana na Płonących Stepach.', '', '', '', '', 0),
(4342, 'plPL', 'Opowieść Kharana', 'Proszę, wysłuchaj mnie, zanim wydasz osąd!$B', 'Wysłuchaj opowieści Kharana Potężnego Młota.', 'Opowieść Kharana', 'Porozmawiaj z Kharanem Potężnym Młotem w Otchłani Czarnej Góry.', '', '', '', '', 0),
(6642, 'plPL', 'Przychylność Bractwa: ruda czarnorytu', '', '', '', 'Wróć do Lokhtosa Ciemnotarga w Górach Alterak.', '', '', '', '', 0),
(6643, 'plPL', 'Przychylność Bractwa: ognisty rdzeń', '', '', '', 'Wróć do Lokhtosa Ciemnotarga w Górach Alterak.', '', '', '', '', 0),
(6644, 'plPL', 'Przychylność Bractwa: rdzeń lawy', '', '', '', 'Wróć do Lokhtosa Ciemnotarga w Górach Alterak.', '', '', '', '', 0),
(6645, 'plPL', 'Przychylność Bractwa: skóra z jądra', '', '', '', 'Wróć do Lokhtosa Ciemnotarga w Górach Alterak.', '', '', '', '', 0),
(6646, 'plPL', 'Przychylność Bractwa: krew góry', '', '', '', 'Wróć do Lokhtosa Ciemnotarga w Górach Alterak.', '', '', '', '', 0),
(7604, 'plPL', 'Wiążący kontrakt', '$gNiżej podpisany:Niżej podpisana; niniejszym oświadcza, że sztabka sulfuronu dostarczana Bractwu Torium (BT sp. z o.o.) jest oryginalna, a nie jej podróbką. $gNiżej podpisany:Niżej podpisana; przyjmuje również do wiadomości, że za wszelkie szkody, jakie mogą $ggo:ją; spotkać w wyniku prób zbudowania, wykucia, znalezienia, stworzenia, sprzedania lub zjedzenia Sulfurasa, BT sp. z o.o. nie ponosi odpowiedzialności ani winy.$B$BPodpisując ten kontrakt, akceptujesz wszystkie zawarte w nim warunki.$B$B_________________$B$BPodpis', 'Oddaj kontrakt Bractwa Torium Lokhtosowi Ciemnotargowi, jeśli chcesz otrzymać plany młota Sulfurona.', '', '', '', '', '', '', 0),
(8619, 'plPL', 'Nestor Głęboki Poranek', '', '', '', '', '', '', '', '', 0),
(11454, 'plPL', 'Odszukaj sabotażystów', 'Ten skrawek papieru najwyraźniej zgubili przez nieuwagę najeźdźcy – Czarnoryci.$B$BPlany są zawiłe i spisane jakąś szyfrowaną odmianą krasnoludzkiego, ale podpis na końcu – „Coren Bimberhaust” – jest dość wyraźny, podobnie jak wzmianka o karczmie „Pod Ponurym Opojem” w głębi Otchłani Czarnej Góry. Odszukaj prowodyra i połóż kres tym najazdom.', 'Znajdź Corena Bimberhausta w karczmie „Pod Ponurym Opojem” w Otchłani Czarnej Góry.', '', '', '', '', '', '', 0),
(12062, 'plPL', 'Obraź Corena Bimberhausta', 'Coren Bimberhaust jest w sąsiedniej sali i podjudza Czarnorytych do kolejnego ataku na Festiwal Piwa. Pokonaj go!$B$BPodejdź do Corena i sprowokuj bójkę. Powiedz mu, że jego piwo nie nadaje się nawet dla świń.$B$BA kiedy to zrobisz, szykuj się do walki. Ostatniego, kto obraził jego trunek... rzucono na pożarcie srogim dzikom.', 'Porozmawiaj z Corenem Bimberhaustem.', '', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(3982, 'plPL', 'Było blisko. Wiedzą już, że tu jesteś... na pewno przyjdą następni.', 0),
(4083, 'plPL', 'Klejnoty bezgłośnie opadają w głąb kielicha...', 0),
(4201, 'plPL', 'Och, udało ci się! Teraz mogę uwarzyć mój eliksir i użyć go na Rocknocie. Wreszcie ulegnie moim wdziękom!$B$BDziękuję ci, $N. Jesteś $gprawdziwym bohaterem:prawdziwą bohaterką; miłości!', 0),
(4241, 'plPL', 'Gdzie on jest! Zamorduję go!', 0),
(4242, 'plPL', 'Najwyraźniej postradał zmysły.$B$B<Maxwell spuszcza głowę w żałobie.>$B$BSzkoda, że niegdyś dumny i szlachetny wojownik stał się bełkoczącym wariatem. CHYBA dotarliśmy do ślepego zaułka...$B$BMuszę cię wynagrodzić za dotychczasowe starania, $N.', 0),
(4264, 'plPL', '<Marszałek Windsor bierze liścik i zaczyna czytać.>', 0),
(4282, 'plPL', '<Marszałek Windsor wyrywa ci z rąk obie tablice.>$B$BMusimy się stąd wydostać!', 0),
(4295, 'plPL', 'Co to? Ach! Pachnie jak piwo Czarnorytych! Trunek zamglił mi wzrok, ale widzę, $gpanie:pani;, że jesteś $gprawdziwym przyjacielem:prawdziwą przyjaciółką;!', 0),
(4322, 'plPL', 'Niesamowite, $N. Po prostu niesamowite. Windsor przemknął tędy niecałe pięć minut temu. Stawia śmiałe zarzuty, ale twierdzi, że ma na nie dowody. Jest teraz w drodze do Wichrogrodu, żeby rozmówić się z Bolvarem i... lady Prestor.', 0),
(4342, 'plPL', 'Jak widzisz, nic nie mogłem zrobić.', 0),
(6642, 'plPL', 'Twoja ofiara przyjęta została. Przychylność $gzyskałeś:zyskałaś;. Kontynuuj, a do pradawnych rzemiosł $gdopuszczony:dopuszczona; zostaniesz.', 0),
(6643, 'plPL', 'Twoja ofiara przyjęta została. Przychylność $gzyskałeś:zyskałaś;. Kontynuuj, a do pradawnych rzemiosł $gdopuszczony:dopuszczona; zostaniesz.', 0),
(6644, 'plPL', 'Twoja ofiara przyjęta została. Przychylność $gzyskałeś:zyskałaś;. Kontynuuj, a do pradawnych rzemiosł $gdopuszczony:dopuszczona; zostaniesz.', 0),
(6645, 'plPL', 'Twoja ofiara przyjęta została. Przychylność $gzyskałeś:zyskałaś;. Kontynuuj, a do pradawnych rzemiosł $gdopuszczony:dopuszczona; zostaniesz.', 0),
(6646, 'plPL', 'Twoja ofiara przyjęta została. Przychylność $gzyskałeś:zyskałaś;. Kontynuuj, a do pradawnych rzemiosł $gdopuszczony:dopuszczona; zostaniesz.', 0),
(7604, 'plPL', 'Przyjemnie było robić z tobą interesy, $N!$B$BW imieniu BT sp. z o.o. życzę ci powodzenia w poszukiwaniach Sulfurasa!', 0),
(11454, 'plPL', 'Wstyd i hańba, mówię wam – hulacie sobie tam na górze, a nie pijecie najlepszego z najlepszych piw: naszego! Zaprosił nas kto na konkurs? A gdzie tam. Powojuje krasnolud w jakiejś wojnie i nagle jego piwo już nie dość dobre! No to tak, potłukliśmy wam trochę beczek, i słusznie!$B$BEee... ale skoro już $gprzebiłeś:przebiłaś; się przez naszą obronę i w ogóle, to może zrobisz coś dla mnie...', 0),
(12062, 'plPL', 'Co? Coś ty $gpowiedział:powiedziała;? Jak śmiesz! Moje piwo bije na głowę wszystkie te pomyje, które leją na Festiwalu Piwa!$b$bZapłacisz mi za tę zniewagę, $N!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(3982, 'plPL', 'Broń się, $ggłupcze:głupia;!', 0),
(4083, 'plPL', 'Widmowy kielich unosi się w powietrzu, powoli wznosząc się i opadając... jakby w rytm gasnącego serca.', 0),
(4201, 'plPL', 'Masz składniki? Pustka w moim sercu grozi, że mnie pochłonie!', 0),
(4264, 'plPL', '<Marszałek Windsor spogląda na liścik w twojej dłoni.>$B$BCo tam masz, $N?', 0),
(4282, 'plPL', 'Wkrótce ta wielka maskarada dobiegnie końca.', 0),
(4295, 'plPL', 'Och, piwo! Zabiłbym za trochę piwa Czarnorytych!! Szybko, trzeźwieję! Wiem to, bo od trzeźwości mętnieje mi w oczach... i przez to wyglądasz jak $r, którego zabiłem w zeszłym tygodniu!', 0),
(4322, 'plPL', 'Wyglądasz na $gwyczerpanego:wyczerpaną;, $n. Może usiądź przy ogniu i odpocznij.', 0),
(4342, 'plPL', 'Pozwól mi dokończyć moją opowieść.', 0),
(6642, 'plPL', 'Czarnoryt, choć w Otchłani go pod dostatkiem, wciąż cennym towarem w Bractwie jest. Święta broń i zbroje Ragnarosa czarnoryt sobie upodobały.$B$BZa każde 10 bryłek rudy czarnorytu, które ofiarujesz, przychylność Bractwa zyskasz.', 0),
(6643, 'plPL', 'Biada tym, którzy los w Ognistej Czeluści kuszą. Śmierć szybko przychodzi – a kara bez litości wymierzana jest.$B$BWielu z Bractwa zginęło, ogniste rdzenie szukając.$B$BOfiaruj 1 ognisty rdzeń, a przychylność Bractwa zyskasz.', 0),
(6644, 'plPL', 'Bractwo Torium w twej niedoli ci współczuje, $N. Dlatego Lokhtos do targowania się upoważniony został.$B$BOfiaruj 1 rdzeń lawy, a przychylność Bractwa zyskasz.', 0),
(6645, 'plPL', 'Wiele świętych receptur skóry ulubieńców Ragnarosa wymaga.$B$BOfiaruj 2 skóry z jądra, zdarte z tlących się zwłok ognistych ogarów z Ognistej Czeluści, a przychylność Bractwa zyskasz.', 0),
(6646, 'plPL', 'Łzy Władcy Ognia to zaiste rzadkie znalezisko.$B$BOfiaruj 1 krew góry, a przychylność Bractwa zyskasz.', 0),
(7604, 'plPL', 'Dobijamy targu?', 0);
