INSERT INTO `page_text_locale` (`ID`, `locale`, `Text`, `VerifiedBuild`) VALUES
(1436, 'plPL', 'Pelver Głębotup$B$BMroczny Opiekun Pelver jest naszym najbardziej czczonym uczniem. Nosi klucz dłużej niż ktokolwiek inny i drogo go to kosztowało. Gdy zostaje wezwany do dźwigania swego brzemienia, strzeże się go w Domostwie.$B$BJego poświęcenie otaczamy czcią, a on pozostanie w naszych sercach przez wiele lat... gdy już pochłonie go ciemność.', 0);
INSERT INTO `gossip_menu_option_locale` (`MenuID`, `OptionID`, `Locale`, `OptionText`, `BoxText`) VALUES
