INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(9156, 0, 0, 'plPL', 'Wasze rządy terroru dobiegają końca! Stawcie czoła zagładzie, śmiertelnicy!');
INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(4873, 'plPL', '', 'Śmierć naszych ciał oznaczała narodziny naszego ducha i naszego świętego zadania.', 0),
(4874, 'plPL', 'Jestem jednym z Siedmiu, a naszym przeznaczeniem jest trzymać straż. Na wieki.', '', 0),
(4875, 'plPL', 'Nasz przywódca, Zgub\'rel, wysłucha wyzwania.', '', 0),
(4876, 'plPL', 'Na zawsze odmówiono mi dotyku kamienia. Nigdy więcej nie zaznam chwały kutego żelaza...', '', 0),
(4877, 'plPL', '', 'Nie możesz przejść. Nie jesteś z naszego rodu ani nie $grzuciłeś:rzuciłaś; wyzwania.', 0),
(4879, 'plPL', 'Nasz los to zguba wszystkich, którzy stają przed Wielkim Ogniem.', '', 0),
(4881, 'plPL', 'Nasza kara jest zarazem naszym błogosławieństwem.', '', 0),
(4892, 'plPL', 'Twoja niewola dobiega końca, Zgub\'rel. Wyzywam cię!', 'Twoja niewola dobiega końca, Zgub\'rel. Wyzywam cię!', 0),
(4894, 'plPL', '$GRzuciłeś:Rzuciłaś; wyzwanie Siedmiu, a teraz zginiesz!', '', 0),
(4897, 'plPL', 'Mrok\'rel, zdradź mi swoje sekrety!', 'Mrok\'rel, zdradź mi swoje sekrety!', 0),
(4898, 'plPL', 'Chcesz poznać dawne rzemiosło? Chcesz wytapiać czarnoryt?$B$BUdobruchaj mnie, $N. Złóż mi ofiarę, a rozważę to!', '', 0),
(4899, 'plPL', 'Masz silną wolę, a twoje zamiary są jasne.$B$BByć może jesteś $ggodzien:godna;...', '', 0),
(4900, 'plPL', '$GZapłaciłem:Zapłaciłam; twoją cenę, Mrok\'rel. Teraz naucz mnie swoich sekretów!', '$GZapłaciłem:Zapłaciłam; twoją cenę, Mrok\'rel. Teraz naucz mnie swoich sekretów!', 0),
(4901, 'plPL', '$GOkazałeś:Okazałaś; swoje pragnienie i $gzapłaciłeś:zapłaciłaś; cennym kamieniem. Nauczę cię...', '', 0),
(4934, 'plPL', 'Z dala od tych beczek!', '', 0),
(4936, 'plPL', 'Zapłacisz za to!', '', 0),
(4944, 'plPL', 'Ragnaros zapanuje niepodzielnie!', 'Ragnaros zapanuje niepodzielnie!', 0),
(4945, 'plPL', 'Napij się, $N. Może to twój ostatni kufel!', 'Napij się, $N. Może to twój ostatni kufel!', 0),
(4946, 'plPL', 'Gdyby nie karczma „Pod Ponurym Opojem”, cały wolny czas schodziłby mi na wyrywaniu skrzydeł smoczym pisklętom.', 'Gdyby nie karczma „Pod Ponurym Opojem”, cały wolny czas schodziłby mi na wyrywaniu skrzydeł smoczym pisklętom.', 0),
(4947, 'plPL', 'Gdyby nie karczma „Pod Ponurym Opojem”, pewnie cały wolny czas schodziłby mi na wyrywaniu skrzydeł smoczym pisklętom.', 'Gdyby nie karczma „Pod Ponurym Opojem”, pewnie cały wolny czas schodziłby mi na wyrywaniu skrzydeł smoczym pisklętom.', 0),
(4948, 'plPL', 'Żywiołaki wody toczą wojnę z żywiołakami ognia, co w pewnym sensie oznacza, że toczą wojnę z nami. Jeden z ich przywódców, Hydraxis, zbiera agentów dla swojej sprawy...', 'Żywiołaki wody toczą wojnę z żywiołakami ognia, co w pewnym sensie oznacza, że toczą wojnę z nami. Jeden z ich przywódców, Hydraxis, zbiera agentów dla swojej sprawy...', 0),
(4950, 'plPL', 'Podobno jeden z możnych wśród żywiołaków wody, Hydraxis, toczy wojnę ze sługami ognia. Miejmy nadzieję, że przegra!', 'Podobno jeden z możnych wśród żywiołaków wody, Hydraxis, toczy wojnę ze sługami ognia. Miejmy nadzieję, że przegra!', 0),
(4951, 'plPL', 'Władca Wody Hydraxis kryje się w Aszarze, na wyspie w Zatoce Burz. Czym ten głupiec może nam stamtąd zagrozić?', 'Władca Wody Hydraxis kryje się w Aszarze, na wyspie w Zatoce Burz. Czym ten głupiec może nam stamtąd zagrozić?', 0),
(4953, 'plPL', 'Jeśli Hydraxis zwerbuje więcej sojuszników do swojej wojny, może to przechylić szalę sił...', 'Jeśli Hydraxis zwerbuje więcej sojuszników do swojej wojny, może to przechylić szalę sił...', 0),
(4954, 'plPL', 'Strzelanie i podpalanie to świetna zabawa, dopóki ktoś nie przegra i nie zginie.', 'Strzelanie i podpalanie to świetna zabawa, dopóki ktoś nie przegra i nie zginie.', 0),
(4956, 'plPL', 'Ojciec mówił mi, że przyjdą takie dni, kiedy zagada do mnie obcy, a ja będę musieć się powstrzymywać, żeby $ggo:jej; nie zabić.', 'Ojciec mówił mi, że przyjdą takie dni, kiedy zagada do mnie obcy, a ja będę musieć się powstrzymywać, żeby $ggo:jej; nie zabić.', 0),
(4961, 'plPL', 'Intruzi!!', '', 0),
