(8401, 'plPL', 'Pokaż mi, do czego mam dostęp, Lokhtosie.', 'Pokaż mi, do czego mam dostęp, Lokhtosie.', 0),
(9483, 'plPL', '<Nie rozumiesz ani słowa z technicznego bełkotu na tym zwoju.>', '', 0),
(9484, 'plPL', '<Na tym pergaminie rozrysowano schemat polowego robota naprawczego.>', '', 0),
(9485, 'plPL', '<Przerysuj schemat do swojego notatnika inżynierskiego.>', '<Przerysuj schemat do swojego notatnika inżynierskiego.>', 0),
