(9487, 'plPL', '<Doskonale znasz budowę i działanie tego robota.>', '', 0),
(27461, 'plPL', 'Och... Kręci mi się w głowie...', '', 0),
(27462, 'plPL', 'Nie przeszkadzaj mi, $N! Mam tu dwa pełne kotły bulgoczącego trunku i muszę dopilnować, żeby smakowały jak należy!$B$BJeśli nie, mistrz Coren Bimberhaust obedrze mnie ze skóry i ugotuje!', '', 0),
(27464, 'plPL', 'Mogę pomóc ci w degustacji?', 'Mogę pomóc ci w degustacji?', 0),
(27468, 'plPL', 'Robi się coraz lepsze! Naprawdę rozgrzewa żołądek! I muszę przyznać, $n, że $gelegancki z ciebie gość:elegancka z ciebie babka;!', '', 0),
(27469, 'plPL', 'Dobre to! Ale trochę za słabe. Chyba dodam jeszcze szczyptę czosnkowego oddechu...', '', 0),
(27487, 'plPL', 'Dobre to! Ale chyba trochę mdłe. Dopełnijmy smak paroma mięciutkimi gałkami ocznymi bazyliszka...', '', 0),
(27488, 'plPL', 'Nieźle, nieźle... Ale brakuje mu pikanterii! Może dodać jadu skorpida? Tak! To załatwi sprawę!', '', 0),
(27489, 'plPL', 'Nabiera kształtu! Ale brakuje mu kopa. Tak, $gzgadłeś:zgadłaś;... Wypierzmy w kotle wczorajsze skarpety... Mmm, pyszne!', '', 0),
(27490, 'plPL', 'Tak, $gpanie:pani;, to jest dopiero trunek! Zaiste, dopiero trunek!', '', 0),
(27491, 'plPL', 'Zaśpiewajmy piosenkę!$B$BWarzyć, bić,$BWarzyć, bić!$BJak Czarnoryt chcę żyć!$B$BHa, ha! $n, lubię cię!', '', 0),
(27492, 'plPL', 'Na czym to stanęło? A, tak... Więc mówię do niej: „Ale ja cię potrzebuję! Potrzebuję cię!”... a ona tylko się zaśmiała i odpełzła! Święta prawda, $n. Nagi potrafią być takie okrutne!', '', 0),
(27493, 'plPL', 'Spróbujmy jeszcze!', 'Spróbujmy jeszcze!', 0),
(27494, 'plPL', 'Jeszcze kolejkę!', 'Jeszcze kolejkę!', 0),
(27515, 'plPL', 'Innego dnia nie byłoby mowy, ale... chce mi się pić, a nie znoszę pić w samotności.$B$BDo dna!', '', 0),
(27516, 'plPL', 'Na zdrowie!', 'Na zdrowie!', 0),
(27594, 'plPL', '', 'Słuchaj, powiedz Schweitzerowi i Roitau, że mamy tu wszystko pod kontrolą. Nie muszą... co?$B$BNie oni cię przysłali? To czemu marnujesz mój czas?$B$BMam robotę!', 0),
(27595, 'plPL', 'Hej, nie widzisz, że jestem zajęta?!$B$BChcesz obejrzeć występ? Zespół gra co wieczór o ósmej.', '', 0),
(27600, 'plPL', 'Ale $gprzyjechałem:przyjechałam; tu swoją maszyną kretową aż z góry...', 'Ale $gprzyjechałem:przyjechałam; tu swoją maszyną kretową aż z góry...', 0),
(27601, 'plPL', 'No... dobra, dobra. I tak musimy przetestować sprzęt.$B$BDaj mi kilka sekund. Każę im wyjść na „próbę”.$B$B$GGotów:Gotowa;?', '', 0),
(27602, 'plPL', 'Jestem $ggotów:gotowa;.', 'Jestem $ggotów:gotowa;.', 0),
